from collections import defaultdict, deque

def bfs(capacity, source, sink):
    queue = deque([source])
    parent = {node: None for node in capacity}
    parent[source] = source

    while queue:
        u = queue.popleft()
        for v in capacity[u]:
            if parent[v] is None and capacity[u][v] > 0:
                parent[v] = u
                if v == sink:
                    return parent
                queue.append(v)

    return None

def edmonds_karp(capacity, source, sink):
    max_flow = 0
    while True:
        path = bfs(capacity, source, sink)
        if path is None:
            break

        flow = float('Inf')
        s = sink
        while s != source:
            u = path[s]
            flow = min(flow, capacity[u][s])
            s = u

        v = sink
        while v != source:
            u = path[v]
            capacity[u][v] -= flow
            capacity[v][u] += flow
            v = u

        max_flow += flow

    return max_flow

