    from itertools import combinations

    # Function to check if two students can work together calmly
    def can_work_together(x, y):
        return (a[x] & a[y]) == 0

    max_sum = 0

    # Check all combinations of students
    for r in range(2, n + 1):
        for combo in combinations(range(n), r):
            valid = True
            for i in range(r):
                for j in range(i + 1, r):
                    if not can_work_together(combo[i], combo[j]):
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                current_sum = sum(b[i] for i in combo)
                if current_sum > max_sum:
                    max_sum = current_sum

    return max_sum

